/*
 * A001326  Number of equivalence classes of n-valued Post functions of 2
 *          variables under action of semi-direct product of symmetric group
 *          S_2 and complementing group D(2,n).
 * https://oeis.org/A001326
 *
 * Offset:    2    (a(2) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = (n^(n^2) + 2*n^(n*ceil(n/2)) + 2*n^(n(n+1)/2) +
 *            n^((n^2+f)/2) + 2*n^((n^2+3f)/4)) / 8, where f = n mod 2
 *            (Burnside over the order-8 group generated by swapping and
 *            complementing inputs)
 * Range:     u8 n <= 2, u16 n <= 3, u32 n <= 4, u64 n <= 5, u128 n <= 6,
 *            big any n
 * Helpers:   a001326_mul, a001326_pow
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include "../utils/a001326_mul.h"
#include "../utils/a001326_pow.h"

seq_t a(idx_t n)
{
    idx_t f = n % 2;
    idx_t h = (n + 1) / 2;
    idx_t ex[5];
    unsigned w[5] = {1, 2, 2, 1, 2};
    seq_t sumT = 0;
    unsigned sumR = 0;
    int i;
    ex[0] = n * n;
    ex[1] = h * n;
    ex[2] = n * (n + 1) / 2;
    ex[3] = (n * n + f) / 2;
    ex[4] = (n * n + 3 * f) / 4;
    for (i = 0; i < 5; i++) {
        seq_t T;
        unsigned R;
        a001326_pow(n, ex[i], &T, &R);
        sumT += T * w[i];
        sumR += R * w[i];
    }
    return sumT + (seq_t)(sumR / 8);
}
